local root=app.params['root'];local dir=root..'/outputs/helicopter-death';local file=io.open(dir..'/editor-plan.json','r');local plan=json.decode(file:read('*a'));file:close();local out=root..'/work/helicopter-death/roundtrip';app.fs.makeAllDirectories(out)
for name,_ in pairs(plan)do local s=app.open(dir..'/editable/'..name..'.aseprite');local count=#s.frames;for _,f in ipairs({1,math.floor(count/2),count})do local im=Image(s.width,s.height,ColorMode.RGB);for _,cel in ipairs(s.cels)do if cel.frame.frameNumber==f then im:drawImage(cel.image,cel.position)end end;im:saveAs(out..'/'..name..'-'..f..'.png')end;s:close()end
